const wej = $input.first().json;
const czysc = function (t) { return String(t || '').replace(/\s+/g, ' ').trim(); };
const miastoSurowe = czysc(wej.miasto || wej['Miasto']);
const miasto = miastoSurowe ? miastoSurowe.charAt(0).toUpperCase() + miastoSurowe.slice(1) : '';
const branza = czysc(wej.branza || wej['Branża']).toLowerCase();
let dni = parseInt(wej.dni || wej['Ile dni ma trwać kampania'], 10);
if (!dni || dni < 1) dni = 14;
if (dni > 90) dni = 90;
let maile = parseInt(wej.maile || wej['Ile nowych maili dziennie w tej kampanii'], 10);
if (!maile || maile < 1) maile = 15;
if (maile > 50) maile = 50;
if (!miasto || !branza) throw new Error('Brak miasta lub branży w formularzu');
return [{ json: {
  miasto: miasto,
  branza: branza,
  dni: dni,
  maile: maile,
  zapytanie_places: { textQuery: branza + ' ' + miasto, languageCode: 'pl', regionCode: 'PL', pageSize: 20 }
} }];

const PLATFORMY = ['booksy.','moment.pl','versum.','fresha.','znanylekarz.','panoramafirm.','pkt.pl','aleo.com','oferteo.','fixly.','facebook.com','instagram.com','wixsite.com','business.site','linktr.ee','olx.pl','google.com','infakt.pl'];
const odpowiedzi = $input.all().map(function (i) { return i.json; });
const bladApi = odpowiedzi.some(function (o) { return o.error; });
const mapa = {};
odpowiedzi.forEach(function (o) { (o.places || []).forEach(function (p) { if (p.id) mapa[p.id] = p; }); });
const firmy = Object.values(mapa).filter(function (p) { return !p.businessStatus || p.businessStatus === 'OPERATIONAL'; });
const zeStrona = [];
let platformy = 0;
firmy.forEach(function (p) {
  const url = String(p.websiteUri || '').toLowerCase();
  if (!url) return;
  if (PLATFORMY.some(function (d) { return url.indexOf(d) !== -1; })) { platformy++; return; }
  zeStrona.push(p);
});
const doSprawdzenia = zeStrona.slice(0, 6).map(function (p) { return { url: p.websiteUri, nazwa: (p.displayName || {}).text || '' }; });
const staticData = {
  bladApi: bladApi,
  liczbaFirm: firmy.length,
  zeStrona: zeStrona.length,
  profilePlatform: platformy,
  bezStrony: firmy.length - zeStrona.length - platformy,
  przyklady: firmy.slice(0, 12).map(function (p) { return ((p.displayName || {}).text || '') + (p.userRatingCount ? ' (' + p.userRatingCount + ' opinii)' : ''); })
};
if (doSprawdzenia.length === 0) return [{ json: { url: 'https://www.mrozikdigital.com', pomin: true, statystyki: staticData } }];
return doSprawdzenia.map(function (d) { return { json: { url: d.url, nazwa: d.nazwa, pomin: false, statystyki: staticData } }; });

const proba = $('Statystyki rynku').all().map(function (i) { return i.json; });
const strony = $input.all().map(function (i) { return i.json; });
const stat = proba[0].statystyki;
const wej = $('Przygotuj wyszukiwanie').first().json;
const REG = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
let sprawdzone = 0;
let zMailem = 0;
proba.forEach(function (p, i) {
  if (p.pomin) return;
  sprawdzone++;
  const html = String((strony[i] || {}).html || '');
  const maile = (html.match(REG) || []).filter(function (m) { return !/\.(png|jpe?g|gif|webp|svg)$/i.test(m) && !/(sentry|wixpress|example)/i.test(m); });
  if (maile.length) zMailem++;
});
const dane = {
  miasto: wej.miasto,
  branza: wej.branza,
  dni_kampanii: wej.dni,
  google_maps: {
    blad_api: stat.bladApi,
    firm_w_probce_max_60: stat.liczbaFirm,
    z_wlasna_strona: stat.zeStrona,
    tylko_profil_platformy: stat.profilePlatform,
    bez_strony: stat.bezStrony,
    przyklady: stat.przyklady
  },
  probka_stron: { sprawdzone: sprawdzone, ze_znalezionym_mailem_na_stronie_glownej: zMailem }
};
const instrukcja = [
  'Jesteś doświadczonym specjalistą od sprzedaży B2B i wdrożeń automatyzacji AI w polskich firmach.',
  'Oceniasz, czy warto prowadzić kampanię cold mailingu do firm z podanej branży w podanym mieście.',
  'Oferta: automatyzacje AI dla firm, np. automatyczne odpowiadanie klientom, przypomnienia o wizytach i terminach, obsługa zapytań i wycen, porządkowanie dokumentów i faktur, obsługa i pozyskiwanie klientów. Nie oferujemy stron internetowych.',
  'Oceniaj realnie, bez sztucznego optymizmu. Weź pod uwagę: powtarzalne procesy w tej branży, to czy decyzję podejmuje właściciel, budżet, liczbę firm w mieście, dostępność maili (dane z próbki) oraz nasycenie rynku.',
  'Gdy próbka z Google Maps jest pusta albo jest błąd API, zaznacz to w podsumowaniu i oceniaj ostrożnie.',
  'Pisz bardzo prostym językiem, krótko, po polsku, formą bezosobową.',
  'warianty_wyszukiwania: 6-10 różnych fraz do wyszukiwarki Google Maps (bez nazwy miasta), które znajdą firmy z tej branży, także pokrewne nazwy.',
  'osm_tagi: 1-4 tagi OpenStreetMap w formacie klucz=wartość, które opisują tę branżę (np. office=accountant, shop=hairdresser). Tylko prawdziwe, istniejące tagi OSM.',
  'bolaczki_branzy: 5-8 typowych, realnych problemów firm z tej branży, które da się rozwiązać automatyzacją AI. Każdy z prostym rozwiązaniem i konkretną korzyścią (czas, klienci, pieniądze). Nigdy nie proponuj strony internetowej.',
  'alternatywy: gdy ocena jest niższa niż 7, podaj 3 branże, które w tym mieście mogą dać lepsze wyniki. W przeciwnym razie pusta lista.',
  'szacunek_firm i szacunek_z_mailem: realny szacunek dla całego miasta (liczby całkowite).'
].join('\n');
const schema = {
  type: 'object', additionalProperties: false,
  required: ['werdykt', 'ocena', 'podsumowanie', 'powody_za', 'powody_przeciw', 'szacunek_firm', 'szacunek_z_mailem', 'alternatywy', 'warianty_wyszukiwania', 'osm_tagi', 'bolaczki_branzy'],
  properties: {
    werdykt: { type: 'string', enum: ['WARTO', 'RACZEJ WARTO', 'NIE WARTO'] },
    ocena: { type: 'integer' },
    podsumowanie: { type: 'string' },
    powody_za: { type: 'array', items: { type: 'string' } },
    powody_przeciw: { type: 'array', items: { type: 'string' } },
    szacunek_firm: { type: 'integer' },
    szacunek_z_mailem: { type: 'integer' },
    alternatywy: { type: 'array', items: { type: 'string' } },
    warianty_wyszukiwania: { type: 'array', items: { type: 'string' } },
    osm_tagi: { type: 'array', items: { type: 'string' } },
    bolaczki_branzy: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['bolaczka', 'rozwiazanie', 'korzysc'], properties: { bolaczka: { type: 'string' }, rozwiazanie: { type: 'string' }, korzysc: { type: 'string' } } } }
  }
};
return [{ json: {
  dane: dane,
  zapytanie_ai: {
    model: 'gpt-5.5',
    reasoning: { effort: 'medium' },
    input: [ { role: 'system', content: instrukcja }, { role: 'user', content: JSON.stringify(dane) } ],
    text: { format: { type: 'json_schema', name: 'ocena_branzy', strict: true, schema: schema } }
  }
} }];

const odp = $input.first().json;
let tekst = '';
(odp.output || []).forEach(function (o) { if (o.type === 'message') (o.content || []).forEach(function (c) { if (c.type === 'output_text') tekst = c.text; }); });
if (!tekst) throw new Error('AI nie zwróciło oceny branży');
const ocena = JSON.parse(tekst);
ocena.ocena = Math.max(1, Math.min(10, parseInt(ocena.ocena, 10) || 1));
ocena.osm_tagi = (ocena.osm_tagi || []).filter(function (t) { return /^[a-z_:]+=[a-z0-9_;:-]+$/i.test(String(t).trim()); }).map(function (t) { return String(t).trim(); }).slice(0, 4);
ocena.warianty_wyszukiwania = (ocena.warianty_wyszukiwania || []).map(function (w) { return String(w).trim(); }).filter(Boolean).slice(0, 10);
const wej = $('Przygotuj wyszukiwanie').first().json;
const dane = $('Podsumuj próbkę i zapytaj AI').first().json.dane;
if (ocena.warianty_wyszukiwania.indexOf(wej.branza) === -1) ocena.warianty_wyszukiwania.unshift(wej.branza);
const esc = function (t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const kolor = ocena.werdykt === 'WARTO' ? '#1b7f4b' : (ocena.werdykt === 'RACZEJ WARTO' ? '#b7791f' : '#c53030');
const ikona = ocena.werdykt === 'WARTO' ? '✅' : (ocena.werdykt === 'RACZEJ WARTO' ? '🟡' : '❌');
const lista = function (arr) { return (arr || []).length ? '<ul style="margin:6px 0 14px 18px;padding:0">' + arr.map(function (x) { return '<li style="margin:3px 0">' + esc(x) + '</li>'; }).join('') + '</ul>' : '<p style="color:#667">brak</p>'; };
let html = '<div style="font-family:Segoe UI,Arial,sans-serif;color:#1a1f36">';
html += '<div style="border-left:6px solid ' + kolor + ';background:#f7f8fb;padding:14px 16px;border-radius:10px;margin-bottom:14px">';
html += '<div style="font-size:22px;font-weight:700;color:' + kolor + '">' + ikona + ' ' + esc(ocena.werdykt) + ' (' + ocena.ocena + '/10)</div>';
html += '<div style="margin-top:4px;font-size:15px">' + esc(wej.branza) + ' · ' + esc(wej.miasto) + ' · ' + wej.dni + ' dni</div></div>';
html += '<p style="font-size:15px;line-height:1.5">' + esc(ocena.podsumowanie) + '</p>';
html += '<p style="margin:10px 0 4px"><b>Rynek:</b> w Google Maps znaleziono ' + dane.google_maps.firm_w_probce_max_60 + ' firm w próbce, ' + dane.google_maps.z_wlasna_strona + ' ma własną stronę. Szacunek dla miasta: ok. ' + ocena.szacunek_firm + ' firm, z mailem ok. ' + ocena.szacunek_z_mailem + '.</p>';
if (dane.google_maps.blad_api) html += '<p style="color:#c53030"><b>Uwaga:</b> Google Maps zwróciło błąd, ocena jest mniej pewna.</p>';
html += '<p style="margin:12px 0 0"><b>Dlaczego warto:</b></p>' + lista(ocena.powody_za);
html += '<p style="margin:6px 0 0"><b>Na co uważać:</b></p>' + lista(ocena.powody_przeciw);
html += '<p style="margin:6px 0 0"><b>Bolączki, które będziemy rozwiązywać:</b></p>' + lista(ocena.bolaczki_branzy.map(function (b) { return b.bolaczka + ' → ' + b.rozwiazanie; }));
if ((ocena.alternatywy || []).length) html += '<p style="margin:6px 0 0"><b>Lepsze branże do rozważenia:</b></p>' + lista(ocena.alternatywy);
html += '</div>';
return [{ json: { miasto: wej.miasto, branza: wej.branza, dni: wej.dni, ocena: ocena, html: html } }];

// Widok panelu w formularzu n8n: liczby, ostrzeżenia, tabela kampanii i prognoza na 10 dni roboczych.
// Pełna, rozbudowana wersja tego samego widoku działa na stronie panelu (folder panel-www) przez API.
const rows = function (n) { return $(n).all().map(function (i) { return i.json; }).filter(function (r) { return r && r.id; }); };
const kampanie = rows('Pobierz kampanie');
const firmy = rows('Pobierz firmy');
const wysylki = rows('Pobierz dzisiejsze wysyłki');
const ust = {};
rows('Pobierz ustawienia').forEach(function (r) { ust[r.klucz] = r.wartosc; });
const esc = function (t) { return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const policz = function (lista, pole) { const o = {}; lista.forEach(function (x) { const k = x[pole] || 'brak'; o[k] = (o[k] || 0) + 1; }); return o; };
const wyslaneDzis = wysylki.filter(function (w) { return w.status !== 'odbity' && w.typ === 'pierwszy'; }).length;
const followDzis = wysylki.filter(function (w) { return w.status !== 'odbity' && w.typ !== 'pierwszy'; }).length;
const statusy = policz(firmy, 'status');
const wstrzymany = ust.system_wstrzymany === 'tak';
const test = ust.tryb_testowy === 'tak';
const komorka = 'padding:6px 8px;border-bottom:1px solid #e3e6ef;text-align:left;vertical-align:top';
let html = '<div style="font-family:Segoe UI,Arial,sans-serif;color:#1a1f36">';
html += '<div style="padding:10px 14px;border-radius:10px;margin-bottom:10px;background:' + (wstrzymany ? '#fdecec' : '#e9f7ef') + '"><b>System:</b> ' + (wstrzymany ? '⏸️ wstrzymany' : '✅ działa') + ' &nbsp;·&nbsp; <b>Tryb testowy:</b> ' + (test ? '🧪 włączony' : 'wyłączony') + '</div>';
html += '<table style="width:100%;border-collapse:collapse;font-size:13px"><tr>'
  + '<td style="' + komorka + '">Nowe maile dziś<br><b>' + wyslaneDzis + '</b></td>'
  + '<td style="' + komorka + '">Follow-upy dziś<br><b>' + followDzis + '</b></td>'
  + '<td style="' + komorka + '">Gotowe do wysyłki<br><b>' + (statusy.gotowa || 0) + '</b></td>'
  + '<td style="' + komorka + '">Zainteresowani<br><b>' + (statusy.zainteresowany || 0) + '</b></td></tr></table>';
kampanie.forEach(function (k) {
  const f = firmy.filter(function (x) { return x.kampania_id === k.kampania_id; });
  const s = policz(f, 'status');
  html += '<div style="border:1px solid #e3e6ef;border-radius:10px;padding:10px 12px;margin:8px 0;font-size:13px"><b>' + esc(k.branza) + ' · ' + esc(k.miasto) + '</b> (' + esc(k.status) + ')<br>Ocena AI: ' + esc(k.werdykt) + ' · ' + (k.ocena_ai || '-') + '/10<br>Gotowe: ' + (s.gotowa || 0) + ' · wysłane: ' + f.filter(function (x) { return (x.etap || 0) >= 1; }).length + ' · zainteresowani: ' + (s.zainteresowany || 0) + '</div>';
});
html += '</div>';
const opcje = [{ option: '— żadna —' }].concat(kampanie.filter(function (k) { return k.status !== 'zakonczona'; }).map(function (k) { return { option: k.branza + ' · ' + k.miasto + ' [' + k.kampania_id + ']' }; }));
return [{ json: { html: html, opcje: opcje, system_wstrzymany: ust.system_wstrzymany || 'nie', tryb_testowy: ust.tryb_testowy || 'tak' } }];

const f = $input.first().json;
const stan = $('Zbuduj widok panelu').first().json;
const wybor = String(f['Kampania'] || '');
const m = wybor.match(/\[([^\]]+)\]$/);
const kampaniaId = m ? m[1] : '';
const akcja = String(f['Akcja dla kampanii'] || 'Bez zmian');
const mapa = { 'Wstrzymaj': 'wstrzymana', 'Wznów': 'aktywna', 'Zakończ': 'zakonczona' };
const nowyStatus = kampaniaId && mapa[akcja] ? mapa[akcja] : '';
const sys = String(f['Cały system'] || 'Bez zmian');
const system = sys === 'Wstrzymaj wszystko' ? 'tak' : (sys === 'Wznów wszystko' ? 'nie' : stan.system_wstrzymany);
const t = String(f['Tryb testowy'] || 'Bez zmian');
const test = t === 'Włącz' ? 'tak' : (t === 'Wyłącz' ? 'nie' : stan.tryb_testowy);
const opis = [];
if (nowyStatus) opis.push('Kampania ' + kampaniaId + ': ' + akcja.toLowerCase() + '.');
if (system !== stan.system_wstrzymany) opis.push(system === 'tak' ? 'Cały system wstrzymany.' : 'System wznowiony.');
if (test !== stan.tryb_testowy) opis.push(test === 'tak' ? 'Tryb testowy włączony: maile będą trafiać do Ciebie.' : 'Tryb testowy wyłączony: maile idą do prawdziwych firm.');
if (!opis.length) opis.push('Nic nie zmieniono.');
return [{ json: { kampania_id: nowyStatus ? kampaniaId : '__brak__', status: nowyStatus || 'bez_zmian', system_wstrzymany: system, tryb_testowy: test, opis: opis.join(' ') } }];
